import{c as a,$ as d,Q as r,j as e,m as o,g as c,o as l}from"./chunks/framework.Ce_49mA8.js";const f=JSON.parse('{"title":"Расход кожи на изделия: нормы на сумку, кошелёк и ремень","description":"Сколько кожи нужно на сумку, рюкзак, кошелёк и ремень в дм² и фут². Формула расхода с КИС, весовой способ замера лекал и перевод единиц измерения.","frontmatter":{"title":"Расход кожи на изделия: нормы на сумку, кошелёк и ремень","description":"Сколько кожи нужно на сумку, рюкзак, кошелёк и ремень в дм² и фут². Формула расхода с КИС, весовой способ замера лекал и перевод единиц измерения.","datePublished":"2026-11-11","dateModified":"2026-11-12","tags":["Раскрой","Кожевенное дело","Нормативы расхода","Экономика цеха"],"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Расход кожи на изделия: нормы на сумку, кошелёк и ремень"}],["meta",{"property":"og:description","content":"Сколько кожи нужно на сумку, рюкзак, кошелёк и ремень в дм² и фут². Формула расхода с КИС, весовой способ замера лекал и перевод единиц измерения."}],["meta",{"property":"og:url","content":"https://omnicraft-erp.com/ru/articles/rashod-kozhi-na-izdeliya"}],["meta",{"property":"og:image","content":"https://omnicraft-erp.com/img/ru/calculators/leather-cost-calculator-og.webp"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"Article\\",\\"headline\\":\\"Расход кожи на изделия: нормы на сумку, кошелёк и ремень\\",\\"description\\":\\"Сколько кожи нужно на сумку, рюкзак, кошелёк и ремень в дм² и фут². Формула расхода с КИС, весовой способ замера лекал и перевод единиц измерения.\\",\\"image\\":[\\"https://omnicraft-erp.com/img/ru/calculators/leather-cost-calculator-og.webp\\"],\\"inLanguage\\":\\"ru-RU\\",\\"mainEntityOfPage\\":\\"https://omnicraft-erp.com/ru/articles/rashod-kozhi-na-izdeliya\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"ОмниКрафт ЕРП\\",\\"url\\":\\"https://omnicraft-erp.com/ru/\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"ОмниКрафт ЕРП\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://omnicraft-erp.com/logo.svg\\"}},\\"datePublished\\":\\"2026-11-11\\",\\"dateModified\\":\\"2026-11-12\\"},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Главная\\",\\"item\\":\\"https://omnicraft-erp.com/ru/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Статьи и руководства\\",\\"item\\":\\"https://omnicraft-erp.com/ru/articles/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"Расход кожи на изделия\\",\\"item\\":\\"https://omnicraft-erp.com/ru/articles/rashod-kozhi-na-izdeliya\\"}]}]}"],["meta",{"property":"article:published_time","content":"2026-11-11"}],["meta",{"property":"article:modified_time","content":"2026-11-12"}]]},"headers":[],"relativePath":"ru/articles/rashod-kozhi-na-izdeliya.md","filePath":"ru/articles/rashod-kozhi-na-izdeliya.md"}'),n={name:"ru/articles/rashod-kozhi-na-izdeliya.md"},i={class:"interactive-frame-container"};function p(g,t,h,m,v,u){const s=d("OmniCraftFrame");return r(),e("div",null,[t[0]||(t[0]=o('<div class="article-breadcrumb"><a href="/ru/articles/">← Все статьи и руководства</a></div><h1 id="расход-кожи-формула-расчета-и-нормы-на-сумку-кошелек-ремень" tabindex="-1">Расход кожи: формула расчёта и нормы на сумку, кошелёк, ремень <a class="header-anchor" href="#расход-кожи-формула-расчета-и-нормы-на-сумку-кошелек-ремень" aria-label="Permalink to &quot;Расход кожи: формула расчёта и нормы на сумку, кошелёк, ремень&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Коротко о норме расхода</p><p>Чтобы списать сырьё без дефицита при крое, суммарную площадь лекал с припусками (<strong>S<sub>лекал</sub></strong>) делят на коэффициент использования сырья (КИС). Для полукожи 1–2 сорта технологический запас сверх чистых деталей составляет <strong>+14–19%</strong> на мелкую галантерею (<code>КИС 0.84–0.88</code>), <strong>+25–32%</strong> на средний крой (<code>0.76–0.80</code>), <strong>+39–47%</strong> на сумки (<code>0.68–0.72</code>) и <strong>+54–67%</strong> на цельные ремни (<code>0.60–0.65</code>). На прямоугольной нарезке форматом А3 отходы снижаются до <strong>9–11%</strong>.</p><p>Ориентиры списания со склада без учёта полного кожаного подклада: <strong>картхолдер</strong> — <code>1.5–5.0 дм²</code>, <strong>складной кошелёк</strong> — <code>7.5–11.0 дм²</code>, <strong>ремень 125–135 см со шкуры</strong> — <code>7.5–9.5 дм²</code>, <strong>поясная сумка (бананка)</strong> — <code>20–30 дм²</code>, <strong>шопер</strong> — <code>65–80 дм²</code>, <strong>дорожная сумка или рюкзак</strong> — <code>100–155 дм²</code>.</p></div><p>При оценке индивидуального заказа перед мастером встают два практических вопроса: какой объём шкуры заложить в смету клиента и какой формат кожи выгоднее оплатить у поставщика — готовый лист А3, вороток или цельную полукожу. Если опереться только на геометрию лицевых стенок, бюджет разойдётся с фактом уже на этапе вырезания ручек, шлёвок и обхода краевых дефектов. Повторная докупка недостающего отреза почти всегда приводит к разнотону: разные партии барабанного крашения отличаются и по оттенку, и по рисунку мереи.</p><p>Ниже собрана прикладная справочная база для кожевенной мастерской: расчётная формула через КИС с таблицей поправок на сортность, нормативы расхода для девяти базовых моделей, три метода быстрого замера сложных выкроек с границами их точности, таблица перевода квадратных футов в дециметры и разбор скрытых потерь в смете.</p><hr><h2 id="_1-базовая-формула-расхода-кожи-и-матрица-кис" tabindex="-1">1. Базовая формула расхода кожи и матрица КИС <a class="header-anchor" href="#_1-базовая-формула-расхода-кожи-и-матрица-кис" aria-label="Permalink to &quot;1. Базовая формула расхода кожи и матрица КИС&quot;">​</a></h2><p>Геометрия бумажных деталей определяет лишь чистую полезную площадь готового изделия. На практике между крупными лекалами образуются острые межлекальные клинья, часть кромки уходит на обход прижизненных пороков, а пашинные участки отсекаются из-за избыточной рыхлости. Анатомическую карту шкуры и механику списания таких выпадов мы подробно разобрали в руководстве <a href="/ru/articles/lovushka-obrezkov-raskroj-kozhi">«Ловушка обрезков: как на самом деле делать раскрой кожи»</a>.</p><p>Чтобы перевести чистую выкройку в реальный складской метраж, используют <strong>коэффициент использования сырья (КИС)</strong> — долю шкуры, которая переходит непосредственно в детали кроя.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Основной норматив расчёта</span><div class="formula-heading">Формула фактического расхода кожи на изделие или партию</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Расход кожи (дм²)</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">S<sub>лекал</sub> (дм²)</span></span><span class="math-denom"><span class="math-var">КИС</span></span></span></div></div></div><p>В числитель подставляют суммарную площадь всех деталей выкройки <strong>уже с припусками на швы, подгибку и подрезку краёв</strong>. Если под рукой есть только чистовые габариты готового корпуса без технологических припусков, сначала умножьте сумму площадей на <code>1.08–1.12</code> (запас +8–12%), и только затем делите на КИС. Например, для сумки с суммарной площадью выкроек <code>49 дм²</code> при <code>КИС = 0.70</code> со склада потребуется <code>49 ÷ 0.70 = 70 дм²</code> (<code>7.5 фут²</code>) кожи.</p><p>Обратите внимание на разницу между долей отходов и запасом к лекалу: когда потери раскроя составляют <code>30%</code> от всей шкуры (<code>КИС = 0.70</code>), к площади бумажных лекал нужно прибавить не 30%, а <code>43%</code> (<code>1 ÷ 0.70 = 1.43</code>).</p><table class="craft-matrix-table"><thead><tr><th style="width:27%;">Категория кроя</th><th style="width:25%;">Какие изделия входят</th><th style="width:16%;">КИС полукожи (1–2 сорт)</th><th style="width:16%;">КИС полукожи (3–4 сорт)</th><th style="width:16%;">Запас к лекалу (1–2 сорт)</th></tr></thead><tbody><tr><td><strong>Крупный крой</strong><br><small style="color:var(--vp-c-text-3);">Детали от 10–25 дм²</small></td><td>Шоперы, портфели, рюкзаки, дорожные сумки</td><td><strong>0.68–0.72</strong></td><td>0.52–0.58</td><td><strong>+39–47%</strong> к лекалу</td></tr><tr><td><strong>Средний крой</strong><br><small style="color:var(--vp-c-text-3);">Детали 3–8 дм²</small></td><td>Длинные портмоне, поясные сумки, папки А4, клатчи</td><td><strong>0.76–0.80</strong></td><td>0.62–0.68</td><td><strong>+25–32%</strong> к лекалу</td></tr><tr><td><strong>Мелкий крой</strong><br><small style="color:var(--vp-c-text-3);">Детали 0.5–2.5 дм²</small></td><td>Складные кошельки, обложки на паспорт, картхолдеры</td><td><strong>0.84–0.88</strong></td><td>0.72–0.76</td><td><strong>+14–19%</strong> к лекалу</td></tr><tr><td><strong>Длинномерный крой</strong><br><small style="color:var(--vp-c-text-3);">Полосы 110–140 см</small></td><td>Брючные ремни, портупеи, цельные плечевые ремни</td><td><strong>0.60–0.65</strong></td><td>0.45–0.50</td><td><strong>+54–67%</strong> к лекалу</td></tr></tbody></table><p>При переходе на сырьё 3–4 сорта за счёт шрамов, клейм и следов овода технологический запас возрастает почти вдвое — от <code>+32%</code> на мелких чехлах до <code>+72–122%</code> на крупных панелях и длинных полосах.</p><div class="warning custom-block"><p class="custom-block-title">Поправка на единичный заказ и серию</p><p>Для штучного заказа из новой полукожи берите нижнюю границу диапазона (для сумки — <code>0.68</code>). При раскрое партии из 5–10 одинаковых сумок крупные стенки укладываются «валетом», а зазоры между ними заполняются ручками, шлёвками и карманами — КИС поднимается на <code>8–12</code> процентных пунктов (до <code>0.78–0.80</code>). В мелкой галантерее резерв роста заметно скромнее (<code>+3–5 п.п.</code>): даже при плотной раскладке на цельной полукоже полезный выход редко превышает <code>0.88–0.90</code> из-за естественной кривизны кромки.</p></div><hr><h2 id="_2-таблица-норм-расхода-кожи-на-популярные-изделия" tabindex="-1">2. Таблица норм расхода кожи на популярные изделия <a class="header-anchor" href="#_2-таблица-норм-расхода-кожи-на-популярные-изделия" aria-label="Permalink to &quot;2. Таблица норм расхода кожи на популярные изделия&quot;">​</a></h2><p>Сколько дм² кожи нужно на сумку, рюкзак или кошелёк? В матрице сведены проверенные цеховые нормативы для изделий без полного кожаного подклада. Цифры пересчитаны по стандарту <code>1 фут² = 9.29 дм²</code> и показывают реальное списание материала со склада.</p><table class="craft-matrix-table"><thead><tr><th style="width:26%;">Изделие и типовые габариты</th><th style="width:15%;">Площадь лекал (дм²)</th><th style="width:10%;">КИС</th><th style="width:23%;">Расход со склада (дм² / фут²)</th><th style="width:26%;">Толщина кожи и формат отреза</th></tr></thead><tbody><tr><td><strong>Компактный картхолдер</strong><br><small style="color:var(--vp-c-text-3);">На 2–3 карты, 10 × 7.5 см</small></td><td>1.2–2.5 дм²</td><td>0.86</td><td><strong>1.5–3.0 дм²</strong><br><small style="color:var(--vp-c-text-3);">0.16–0.32 фут²</small></td><td>1.2–1.4 мм. Кроится из деловых остатков</td></tr><tr><td><strong>Картхолдер многослойный</strong><br><small style="color:var(--vp-c-text-3);">На 4–6 карт с хлястиком</small></td><td>3.0–4.2 дм²</td><td>0.85</td><td><strong>3.5–5.0 дм²</strong><br><small style="color:var(--vp-c-text-3);">0.38–0.54 фут²</small></td><td>1.0–1.4 мм. Умещается на 1 лист А4</td></tr><tr><td><strong>Обложка на паспорт</strong><br><small style="color:var(--vp-c-text-3);">Разворот 20 × 14 см + клапаны</small></td><td>4.5–6.5 дм²</td><td>0.82</td><td><strong>5.5–8.0 дм²</strong><br><small style="color:var(--vp-c-text-3);">0.59–0.86 фут²</small></td><td>1.2–1.6 мм. От 1 листа А4 до формата А3</td></tr><tr><td><strong>Складной кошелёк</strong><br><small style="color:var(--vp-c-text-3);">На 4–6 карт, без монетницы</small></td><td>6.0–8.5 дм²</td><td>0.80</td><td><strong>7.5–11.0 дм²</strong><br><small style="color:var(--vp-c-text-3);">0.81–1.18 фут²</small></td><td>1.2–1.5 мм (верх) + 0.8–1.0 мм (карманы). Лист А3</td></tr><tr><td><strong>Длинное портмоне</strong><br><small style="color:var(--vp-c-text-3);">Под купюры без сгиба, 19 × 10 см</small></td><td>10–14 дм²</td><td>0.78</td><td><strong>13–18 дм²</strong><br><small style="color:var(--vp-c-text-3);">1.40–1.94 фут²</small></td><td>1.2–1.6 мм (верх) + 0.8–1.0 мм (слоты). Отрез от 20 дм²</td></tr><tr><td><strong>Ремень брючный / джинсовый</strong><br><small style="color:var(--vp-c-text-3);">Ширина 35–40 мм, длина 125–135 см</small></td><td>4.8–5.6 дм²</td><td>0.62*</td><td><strong>7.5–9.5 дм²</strong><br><small style="color:var(--vp-c-text-3);">0.81–1.02 фут²</small></td><td>3.5–4.0 мм. Чепрак строго вдоль хребта</td></tr><tr><td><strong>Поясная сумка / малая сумка</strong><br><small style="color:var(--vp-c-text-3);">Через плечо (бананка), ~22 × 14 × 6 см</small></td><td>15–22 дм²</td><td>0.75</td><td><strong>20–30 дм²</strong><br><small style="color:var(--vp-c-text-3);">2.15–3.23 фут²</small></td><td>1.4–1.8 мм. Отрез 30+ дм² или плотный вороток</td></tr><tr><td><strong>Сумка-шопер</strong><br><small style="color:var(--vp-c-text-3);">Открытая, ~35 × 38 × 10 см</small></td><td>45–56 дм²</td><td>0.70</td><td><strong>65–80 дм²</strong><br><small style="color:var(--vp-c-text-3);">7.00–8.61 фут²</small></td><td>1.4–2.0 мм. Крупный чепрак или полукожа от 90 дм²</td></tr><tr><td><strong>Дорожная сумка / рюкзак / портфель</strong><br><small style="color:var(--vp-c-text-3);">Каркас ~40–50 см с карманами</small></td><td>70–105 дм²</td><td>0.68</td><td><strong>100–155 дм²</strong><br><small style="color:var(--vp-c-text-3);">10.8–16.7 фут²</small></td><td>1.6–2.4 мм. Цельная полукожа от 150–180 дм²</td></tr></tbody></table><p>* Для ремня в матрице показан расход кожи при нарезке с цельной полукожи. При покупке готовой ременной заготовки (например, <code>4 × 135 см</code>) отходы сводятся к обрезке хвоста и пряжки, поэтому фактический расход составляет <strong>5.5–6.5 дм²</strong>. Монетница с объёмными боковинками и перегородками добавляет к складному кошельку ещё <code>2.5–3.5 дм²</code> по раскрою — в один стандартный лист А3 (<code>12.47 дм²</code>) такая модель уже не помещается.</p><div class="tip custom-block"><p class="custom-block-title">Поправка на полный кожаный подклад</p><p>Если вы шьёте сумку или рюкзак не с текстильной подкладкой, а с подкладом из тонкой кожи (подкладочная коза или КРС <code>0.6–0.9 мм</code>), добавляйте к сметной площади верха <strong>65–90%</strong> площади подкладочной кожи. Поправка меньше 100%, потому что ручки, плечевые ремни и наружные хлястики подкладом не дублируются; при этом мелкие шкурки козы (<code>60–90 дм²</code>) дают заметно больше угловых выпадов на деталях крупных стенок. Для сумки с расходом верха <code>70 дм²</code> потребуется дополнительно <code>45–63 дм²</code> подкладочной кожи.</p></div><p>Чтобы сразу перевести найденный метраж в бюджет заказа с учётом фурнитуры, клея, финиша уреза и времени работы, подставьте норму из таблицы в наш <a href="/ru/calculators/leather-cost-calculator">бесплатный калькулятор себестоимости изделий из кожи</a>.</p><hr><h2 id="_3-как-рассчитать-расход-для-своеи-модели-за-2-минуты" tabindex="-1">3. Как рассчитать расход для своей модели за 2 минуты <a class="header-anchor" href="#_3-как-рассчитать-расход-для-своеи-модели-за-2-минуты" aria-label="Permalink to &quot;3. Как рассчитать расход для своей модели за 2 минуты&quot;">​</a></h2><p>Для нестандартного заказа, когда готовых табличных ориентиров недостаточно, подходят три быстрых способа оценки — каждый со своими допущениями и границами точности.</p><h3 id="способ-1-объемная-развертка-корпуса-без-готовои-выкроики" tabindex="-1">Способ 1. Объёмная развёртка корпуса без готовой выкройки <a class="header-anchor" href="#способ-1-объемная-развертка-корпуса-без-готовои-выкроики" aria-label="Permalink to &quot;Способ 1. Объёмная развёртка корпуса без готовой выкройки&quot;">​</a></h3><p>Если клиент прислал только желаемые внешние габариты сумки (<code>Длина × Высота × Глубина</code>), корпус легко разложить в плоские прямоугольники стенок и единого ботана.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Быстрая оценка без выкройки</span><div class="formula-heading">Площадь открытого корпуса сумки по габаритам (Д × В × Г в см)</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">S<sub>корпуса</sub> (дм²)</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">2 × Д × В + Г × (Д + 2 × В)</span></span><span class="math-denom"><span class="math-var">100</span></span></span></div></div></div><p>Разберём расчёт на примере повседневной сумки размером <strong>32 × 26 × 9 см</strong>:</p><ol class="craft-ordered-list"><li><div><strong>Считаем переднюю и заднюю стенки:</strong> 2 × 32 × 26 = <strong>1 664 см²</strong> (16.64 дм²).</div></li><li><div><strong>Считаем ботан (дно и две боковины):</strong> 9 × (32 + 2 × 26) = 9 × 84 = <strong>756 см²</strong> (7.56 дм²).</div></li><li><div><strong>Складываем корпус и прибавляем оснастку:</strong> 16.64 + 7.56 = <strong>24.20 дм²</strong>; добавляем 20% на ручки, внутренний карман и припуски шва — 24.20 × 1.20 = <strong>29.04 дм²</strong> чистых лекал.</div></li><li><div><strong>Пересчитываем через КИС крупного кроя (0.70):</strong> 29.04 ÷ 0.70 = <strong>41.5 дм²</strong> (4.47 фут²), то есть в смету закладываем отрез от 43–45 дм².</div></li></ol><p><strong>Где метод даёт погрешность:</strong> приведённая формула описывает открытый короб без верха (шопер или тоут). Если в сумке или рюкзаке предусмотрена закрытая верхняя планка под молнию (ботан охватывает весь периметр <code>2 × Д + 2 × В</code>), добавьте к результату площадь верхней грани <code>Г × Д ÷ 100</code>. Для моделей с большим перекидным клапаном накидывайте не <code>20%</code>, а <code>30–40%</code> на оснастку.</p><h3 id="способ-2-весовои-гравиметрическии-замер-криволинеиных-лекал" tabindex="-1">Способ 2. Весовой (гравиметрический) замер криволинейных лекал <a class="header-anchor" href="#способ-2-весовои-гравиметрическии-замер-криволинеиных-лекал" aria-label="Permalink to &quot;Способ 2. Весовой (гравиметрический) замер криволинейных лекал&quot;">​</a></h3><p>Сложные выкройки с радиусными вырезами, скруглениями и вытачками неудобно разбивать на геометрические фигуры и долго считать по клеточкам на миллиметровке. Намного быстрее взвесить готовые картонные детали, ведь у плотного электрокартона или ватмана из одной пачки масса строго пропорциональна площади.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Точность ±1.5% при шаге весов 0.1 г</span><div class="formula-heading">Гравиметрическая формула площади вырезанных лекал</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">S<sub>лекал</sub> (дм²)</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">Масса всех лекал (г)</span></span><span class="math-denom"><span class="math-var">Масса эталона А4 (г)</span></span></span><span class="math-op">×</span><span class="math-var">6.24 дм²</span></div></div></div><p>Порядок замера в мастерской:</p><ol class="craft-ordered-list"><li><div><strong>Взвесьте эталонный лист:</strong> положите на ювелирные весы целый лист того же картона форматом А4 (21.0 × 29.7 см = <strong>6.24 дм²</strong>). Лист плотностью 300 г/м² весит около <strong>18.7 г</strong>.</div></li><li><div><strong>Взвесьте весь комплект выкройки:</strong> соберите на весах все картонные детали рюкзака уже с припусками (в примере стопка показала <strong>135.0 г</strong>).</div></li><li><div><strong>Вычислите чистую площадь:</strong> (135.0 ÷ 18.7) × 6.24 = <strong>45.05 дм²</strong>.</div></li><li><div><strong>Переведите в закупку по КИС (0.70):</strong> 45.05 ÷ 0.70 = <strong>64.4 дм²</strong> (6.93 фут²).</div></li></ol><p><strong>Где метод даёт погрешность:</strong> заявленная точность <code>±1.5%</code> держится лишь при трёх условиях. Во-первых, эталон А4 обязан быть из той же пачки и влажности, что и выкройка: плотность картона разных партий гуляет на <code>3–5%</code>, а сырой лист тяжелее сухого. Во-вторых, обычные кухонные весы с шагом <code>1 г</code> не подходят для мелкой галантереи (<code>&lt; 10 дм²</code>): на лекалах суммарным весом <code>6–10 г</code> погрешность одного деления весов достигает <code>10–15%</code>, поэтому нужны весы с точностью <code>0.1 г</code>. В-третьих, с деталей перед взвешиванием нужно снять малярный скотч, металлические скрепки и лишние обрезки.</p><h3 id="способ-3-длина-полосы-и-расход-кожи-для-ремня" tabindex="-1">Способ 3. Длина полосы и расход кожи для ремня <a class="header-anchor" href="#способ-3-длина-полосы-и-расход-кожи-для-ремня" aria-label="Permalink to &quot;Способ 3. Длина полосы и расход кожи для ремня&quot;">​</a></h3><p>С ременной продукцией ориентироваться только на площадь бессмысленно: четыре квадрата <code>10 × 10 см</code> дают те же <code>4 дм²</code>, но собрать из них надёжный ремень нельзя. Ременная полоса кроится цельным отрезом строго параллельно хребту (в поперечном направлении кожа под нагрузкой вытягивается за первый месяц носки).</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Ременной норматив</span><div class="formula-heading">Необходимая длина ременной заготовки под обхват по поясу</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">L<sub>заготовки</sub> (см)</span><span class="math-op">=</span><span class="math-var">Обхват по поясу (см)</span><span class="math-op">+</span><span class="math-var">18 см (хвост)</span><span class="math-op">+</span><span class="math-var">8 см (подгиб под пряжку)</span></div></div></div><p>При обхвате по поясу <strong>95 см</strong> заготовка получается <code>95 + 18 + 8 = 121 см</code> (с технологическим запасом под подрезку берут <strong>125–130 см</strong>). При ширине <code>3.8 см</code> сама полоса занимает <code>12.5 × 0.38 = 4.75 дм²</code>, а вместе с двумя шлёвками чистая площадь достигает <strong>5.1 дм²</strong>. Когда такую длинную полосу отрезают от цельной полукожи, косые клинья шеи и огузка снижают КИС до <code>0.62</code>, и со склада списывается уже <strong>8.2 дм²</strong>.</p><p><strong>Где метод даёт погрешность:</strong> измеряйте обхват именно поверх брюк по линии ременных петель (до среднего отверстия), а не по размеру талии или ярлыку джинсов — разница обычно составляет <code>5–8 см</code>. Если же ставится винтовая или зажимная пряжка без перегиба кожи, вместо <code>8 см</code> достаточно оставить <code>3–4 см</code> на крепление язычка или винта.</p><div class="download-banner"><div class="download-info"><div class="download-title">Единый шаблон расчёта расхода и себестоимости кожи в Excel</div><div class="download-desc">Закрытые от случайного сбоя формулы без макросов: подставьте площадь лекал, процент потерь на крой и цену шкуры — таблица сама рассчитает смету.</div></div><div style="display:flex;gap:8px;flex-wrap:wrap;"><a href="/downloads/omnicraft_leather_cost_calculator.xlsx" download="ОмниКрафт_Калькулятор_раскроя_и_себестоимости_кожи.xlsx" class="vp-button brand" data-omni-event="article_download_leather_xlsx"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" y1="15" x2="12" y2="3"></line></svg><span>Скачать шаблон Excel (.xlsx)</span></a></div></div><hr><h2 id="_4-перевод-единиц-измерения-дм2-квадратные-футы-м2-и-форматы-а4-а3" tabindex="-1">4. Перевод единиц измерения: дм², квадратные футы, м² и форматы А4/А3 <a class="header-anchor" href="#_4-перевод-единиц-измерения-дм2-квадратные-футы-м2-и-форматы-а4-а3" aria-label="Permalink to &quot;4. Перевод единиц измерения: дм², квадратные футы, м² и форматы А4/А3&quot;">​</a></h2><p>Российские оптовики и кожзаводы маркируют шкуры в <strong>квадратных дециметрах (дм²)</strong>, а итальянские, турецкие и американские фабрики ставят на бахтарме клеймо в <strong>квадратных футах (фут²)</strong>. Эта сводная таблица снимает путаницу при проверке накладной.</p><table class="craft-matrix-table"><thead><tr><th style="width:24%;">Величина / Формат</th><th style="width:22%;">Квадратные дециметры (дм²)</th><th style="width:22%;">Квадратные футы (стандарт 9.29)</th><th style="width:16%;">Квадратные метры (м²)</th><th style="width:16%;">Ориентир в листах А4</th></tr></thead><tbody><tr><td><strong>1 квадратный фут (12×12 дюймов)</strong></td><td><strong>9.29 дм²</strong></td><td>1.00 фут²</td><td>0.093 м²</td><td>~1.49 листа А4</td></tr><tr><td><strong>Лист формата А4 (21×29.7 см)</strong></td><td><strong>6.24 дм²</strong></td><td>0.67 фут²</td><td>0.062 м²</td><td>1.00 лист А4</td></tr><tr><td><strong>Лист формата А3 (29.7×42 см)</strong></td><td><strong>12.47 дм²</strong></td><td>1.34 фут²</td><td>0.125 м²</td><td>2.00 листа А4</td></tr><tr><td><strong>Малый отрез (5 футов²)</strong></td><td><strong>46.45 дм²</strong></td><td>5.00 фут²</td><td>0.465 м²</td><td>~7.4 листа А4</td></tr><tr><td><strong>Средний вороток (10 футов²)</strong></td><td><strong>92.90 дм²</strong></td><td>10.00 фут²</td><td>0.929 м²</td><td>~14.9 листа А4</td></tr><tr><td><strong>Стандартная полукожа (18 футов²)</strong></td><td><strong>167.2 дм²</strong></td><td>18.00 фут²</td><td>1.672 м²</td><td>~26.8 листа А4</td></tr><tr><td><strong>1 квадратный метр</strong></td><td><strong>100.0 дм²</strong></td><td>10.76 фут²</td><td>1.000 м²</td><td>~16.0 листов А4</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Перевод дм² в см² и квадратные метры за секунду</p><p>Метрическая линейка площади строится на кратности ста: <strong>1 дм² = 100 см²</strong> (квадрат <code>10 × 10 см</code>), а <strong>1 м² = 100 дм² = 10 000 см²</strong>. Чтобы перевести площадь выкройки из сантиметров в дециметры, разделите число на <code>100</code> (например, <code>1 250 см² = 12.5 дм²</code>). Точный перевод из футов: <code>1 фут² = 9.29 дм²</code> или <code>929 см²</code>, а обратно из дециметров в футы — деление на <code>9.29</code> (или умножение на <code>0.1076</code>).</p></div><h3 id="как-проверить-клеимо-поставщика-и-выбрать-формат-закупки" tabindex="-1">Как проверить клеймо поставщика и выбрать формат закупки <a class="header-anchor" href="#как-проверить-клеимо-поставщика-и-выбрать-формат-закупки" aria-label="Permalink to &quot;Как проверить клеймо поставщика и выбрать формат закупки&quot;">​</a></h3><p>На бахтарме импортных шкур после целого числа часто стоят дробные отметки с шагом в четверть фута (<code>15 ¼</code> или <code>15.25</code>, где каждая четверть равна <code>2.32 дм²</code>). В счетах здесь встречаются две противоположные ошибки перевода. Первая случается при округлении коэффициента вниз до <code>9.0</code> при пересчёте рублевой цены за дециметр: если шкура стоит <code>2 800 ₽/фут²</code>, то при делении на <code>9.0</code> цена за дм² выходит <code>311.1 ₽</code> вместо реальных <code>301.4 ₽</code> (<code>2 800 ÷ 9.29</code>). Скрытая наценка равна <strong>+3.2%</strong> — на полукоже в <code>180 дм²</code> это переплата около <code>1 750 ₽</code> (эквивалент <code>5.8 дм²</code> кожи). Вторая ошибка — бытовой миф «в одном футе 10 дм²»: ожидая получить с полукожи <code>18 фут²</code> ровно <code>180 дм²</code>, вы фактически получаете <code>167.2 дм²</code>, и этих <code>12.8 дм²</code> недостачи хватает, чтобы сорвать раскрой последней детали сумки.</p><p>Отдельный выбор — покупка прямоугольной нарезки форматом <code>А3</code> (<code>12.47 дм²</code>) вместо целой полукожи. В нарезке уже удалены рыхлые полы и неровные края, поэтому КИС на кошельках и картхолдерах поднимается до <code>0.90–0.92</code>, а потери падают до <code>9–11%</code>. Платить за такое удобство приходится ценой за квадратный дециметр, которая на <code>25–40%</code> выше оптовой цены полукожи. Поэтому готовые отрезы выгодны под разовый штучный заказ или редкий цвет, тогда как регулярные модели рентабельнее кроить с целых шкур.</p><hr><h2 id="_5-четыре-скрытых-просчета-в-смете-которые-съедают-маржу" tabindex="-1">5. Четыре скрытых просчёта в смете, которые съедают маржу <a class="header-anchor" href="#_5-четыре-скрытых-просчета-в-смете-которые-съедают-маржу" aria-label="Permalink to &quot;5. Четыре скрытых просчёта в смете, которые съедают маржу&quot;">​</a></h2><p>При согласовании цены под заказ основной расход обычно уходит в смету верно, а маржа теряется на второстепенных конструктивных узлах и характеристиках конкретной партии кожи.</p><p>Чаще всего из расчёта корпуса выпадает <strong>фурнитурная обвязка</strong> — полукольца под карабины, шлёвки, подкладки под пряжки, хлястики молний и обтачки карманов. На шопере с площадью основных деталей <code>45 дм²</code> такие мелкие элементы добавляют <code>18%</code> чистой площади (<code>+8.1 дм²</code>), что при <code>КИС = 0.70</code> тянет со шкуры <code>11.6 дм²</code>. При закупочной цене кожи <code>55 ₽/дм²</code> забытый узел обвязки оборачивается потерей <strong>640 ₽</strong> на одном изделии.</p><p>Второй источник перерасхода возникает при подстановке <strong>усреднённого КИС без поправки на зону шкуры</strong>. Коэффициенты для чепрака (<code>0.85–0.88</code>), воротка (<code>0.70–0.75</code>) и полы (<code>0.50–0.55</code>) различаются радикально. Если заложить в калькуляцию чепрачный КИС <code>0.85</code>, а затем вырезать крупные детали из полы с выходом <code>0.52</code>, фактическое потребление кожи вырастет на <strong>63%</strong> (<code>0.85 ÷ 0.52 = 1.63</code>), оставив гору краевого лоскута. Как вернуть часть этих денег через рассортировку остатков и мелкую галантерею, разобрано в статье <a href="/ru/articles/chto-delat-s-obrezkami-kozhi">«Что делать с обрезками кожи: 5 способов монетизации»</a>.</p><p>При пошиве с <strong>подгибкой края внутрь</strong> бюджет часто режут забытые припуски по периметру каждой детали (обычно <code>7–10 мм</code>). Возьмём длинное портмоне, где подгибаются две основные панели — наружная стенка <code>19 × 20 см</code> и внутренняя основа <code>19 × 18 см</code>. Припуск <code>8 мм</code> расширяет габариты до <code>20.6 × 21.6 см</code> и <code>20.6 × 19.6 см</code>, добавляя ровно <code>1.27 дм²</code> чистой площади к выкройке, а с поправкой на <code>КИС 0.78</code> — около <strong>+1.6 дм²</strong> дополнительного расхода со шкуры.</p><p>Наконец, попытка сэкономить <code>3–5%</code> площади за счёт <strong>разворота ручек или ремешков поперёк хребта</strong> почти всегда приводит к переделке заказа. В поперечном направлении дерма тянется на <code>15–25%</code> сильнее: ручка длиной <code>50 см</code> под ежедневной нагрузкой вытягивается на <strong>1.5–2.0 см</strong> за первые недели носки, деформируя геометрию всей сумки.</p><hr><h2 id="_6-часто-задаваемые-вопросы" tabindex="-1">6. Часто задаваемые вопросы <a class="header-anchor" href="#_6-часто-задаваемые-вопросы" aria-label="Permalink to &quot;6. Часто задаваемые вопросы&quot;">​</a></h2><div class="craft-faq-accordion"><details class="faq-item"><summary class="faq-summary">Как изменится расход кожи при переходе с толщины 1.4 мм на 2.2 мм?</summary><div class="faq-content"><p> Рост толщины на 0.8 мм увеличивает чистую площадь выкройки примерно на <strong>3–6%</strong> в конструкциях со сгибами и объёмным ботаном. На развороте в 180° толстая кожа «съедает» внутренний радиус (<code>~2 × толщина</code>, то есть 4.4 мм вместо 2.8 мм на каждом сгибе), а припуски по шву на углах приходится расширять на 1.5–2 мм. При этом жёсткая кожа 2.2 мм часто держит форму без уплотнителя и второго слоя, что в сумме иногда снижает общий расход на слоистых моделях. </p></div></details><details class="faq-item"><summary class="faq-summary">Какой запас оставлять при крое деталей под склейку с последующей обрезкой в край?</summary><div class="faq-content"><p> Когда внутренний карман или подкладочную панель приклеивают с напуском, чтобы затем чисто подрезать по линейке после схватывания клея, добавляйте <strong>3–5 мм</strong> с каждой стороны подрезаемой заготовки. Для стенки шопера 35 × 38 см припуск 4 мм по периметру увеличивает площадь детали на <strong>~0.59 дм² (+4.4%)</strong>. В серийных заказах проще кроить в точный размер с пробойниками и совмещением краёв, убирая этот отход. </p></div></details><details class="faq-item"><summary class="faq-summary">Как считать расход на двухцветное или комбинированное изделие?</summary><div class="faq-content"><p> Нельзя складывать всю выкройку и делить на один общий КИС. Считайте <strong>S<sub>лекал</sub></strong> и коэффициент выхода <strong>отдельно по каждому артикулу кожи</strong>. Основные панели (передняя и задняя стенки, ботан) идут по КИС крупного кроя (0.68–0.72), а контрастные хлястики, карманы или вставки обычно кроятся из деловых остатков другого цвета с КИС 0.85–0.90. </p></div></details><details class="faq-item"><summary class="faq-summary">Нужен ли дополнительный припуск при мокром формовании и шитье «выворотных» сумок?</summary><div class="faq-content"><p> При мокром формовании чехлов и футляров на колодке по всему периметру заготовки оставляют технологическую «юбку» шириной 1.5–2.5 см под гвозди или зажимы, которую после высыхания полностью срезают — это увеличивает расход на <strong>15–25%</strong> сверх площади матрицы. Для мягких выворотных сумок лишнего припуска на выворачивание не нужно: мягкая хромовая кожа после выворота и простукивания шва сохраняет проектную площадь с погрешностью в пределах 1–2%. </p></div></details><details class="faq-item"><summary class="faq-summary">Как закладывать в смету покупную ременную полосу вместо раскроя целого чепрака?</summary><div class="faq-content"><p> При использовании готовой нарезанной заготовки (например, 38 × 1350 мм) списание идёт не по длинномерному КИС полукожи (0.62), а по фактической штучной цене полосы или с минимальным технологическим отходом <strong>3–6%</strong> на скругление кончика и пробивку. Если ремень укорачивается с 135 до 115 см, оставшиеся 20 см полосы полностью покрывают два тренчика, и сметные потери стремятся к нулю. </p></div></details></div><hr><h2 id="_7-нормирование-расхода-и-расчет-партии-в-«омникрафт-ерп»" tabindex="-1">7. Нормирование расхода и расчёт партий в «ОмниКрафт ЕРП» <a class="header-anchor" href="#_7-нормирование-расхода-и-расчет-партии-в-«омникрафт-ерп»" aria-label="Permalink to &quot;7. Нормирование расхода и расчёт партий в «ОмниКрафт ЕРП»&quot;">​</a></h2><p>Удерживать в таблице Excel нормы по десяткам моделей, пересчитывать квадратные футы от разных поставщиков в дециметры и обновлять смету при каждом подорожании кожи быстро становится рутиной. Стоит ошибиться в одной ячейке с коэффициентом потерь — и заказ уходит в цех с заниженной ценой.</p><p>Настольная система связывает технологическую карту, складские партии сырья и фактическое списание материалов в одном рабочем окне:</p>',65)),c("div",i,[l(s,{screen:"calculator",slider:"",zoomable:"",lang:"ru",caption:"Интерфейс расчёта себестоимости партии в «ОмниКрафт ЕРП»: спецификация расхода сырья с поправкой на обрезки и брак, нормо-часы, накладные расходы мастерской и запуск партии кнопкой «В производство»"})]),t[1]||(t[1]=o('<p>В программе <strong>«ОмниКрафт ЕРП»</strong> вы заносите чистый расход и поправку на крой в технологическую карту изделия один раз. При расчёте новой партии система автоматически подставляет актуальную среднюю цену кожи со склада по методу скользящей средней (МАК), пересчитывает потребность в сырье, добавляет время работы и накладные расходы и одним нажатием кнопки бронирует материал под заказ.</p><div class="cta-grid"><div class="cta-card featured-cta"><div><div class="cta-card-badge brand-badge">Программа для мастерской</div><h3>ОмниКрафт ЕРП для кожевников</h3><p> Технологические карты с нормами расхода, учёт полукож и деловых остатков по методу МАК, контроль маржи каждого заказа. До 20 продаж — бесплатно. </p></div><a href="/ru/docs/getting-started" class="vp-button brand cta-icon-btn"><span>Попробовать бесплатно</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="cta-btn-icon"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></a></div><div class="cta-card"><div><div class="cta-card-badge">Бесплатный инструмент</div><h3>Калькулятор себестоимости кожи</h3><p> Подставьте площадь кроя, процент потерь на обрезки, фурнитуру и время работы — получите минимальную отпускную цену за 1 минуту. </p></div><a href="/ru/calculators/leather-cost-calculator" class="vp-button alt cta-icon-btn"><span>Открыть калькулятор</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="cta-btn-icon"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></a></div></div><hr><h2 id="связанные-статьи-производственного-кластера" tabindex="-1">Связанные статьи производственного кластера <a class="header-anchor" href="#связанные-статьи-производственного-кластера" aria-label="Permalink to &quot;Связанные статьи производственного кластера&quot;">​</a></h2><ul><li><a href="/ru/articles/lovushka-obrezkov-raskroj-kozhi">Ловушка обрезков: как на самом деле делать раскрой кожи и считать полезную площадь</a> — топография чепрака, воротка и полы, матрица КИС, 10 правил раскроя и эффективная цена полезного дециметра.</li><li><a href="/ru/articles/chto-delat-s-obrezkami-kozhi">Что делать с обрезками кожи: 5 способов монетизации и учёт деловых остатков</a> — сортировка лоскута на 3 фракции, таблица быстрой микрогалантереи, продажа наборов и правило 6 месяцев.</li><li><a href="/ru/calculators/leather-cost-calculator">Калькулятор себестоимости изделий из кожи онлайн</a> — расчёт сметы с учётом потерь раскроя, химии уреза, амортизации и стоимости часа мастера.</li><li><a href="/ru/articles/pricing-and-margins">Ценообразование, наценка и маржа: как не работать в минус</a> — расчёт розничной цены от себестоимости и контроль точки безубыточности мастерской.</li><li><a href="/ru/articles/cost-calculation-software">Программы для расчёта себестоимости: почему Excel и 1С не подходят малым мастерским</a> — разбор скрытых ошибок ручных таблиц и сравнение учётных систем для ремесла.</li></ul>',5))])}const y=a(n,[["render",p]]);export{f as __pageData,y as default};
